CREATE FUNCTION savings_reference_fixing_immutable() RETURNS trigger AS $$
BEGIN
  IF TG_OP='DELETE' OR OLD.status IN ('APPROVED','REJECTED') THEN
    RAISE EXCEPTION 'Reference fixing history is immutable';
  END IF;
  IF (NEW.reference_id,NEW.version,NEW.annual_rate_percent,NEW.publication_date,NEW.effective_date,
      NEW.source_reference,NEW.note,NEW.base_version,NEW.maker_id,NEW.captured_at)
    IS DISTINCT FROM (OLD.reference_id,OLD.version,OLD.annual_rate_percent,OLD.publication_date,OLD.effective_date,
      OLD.source_reference,OLD.note,OLD.base_version,OLD.maker_id,OLD.captured_at) THEN
    RAISE EXCEPTION 'Reference observation is immutable; capture a new version';
  END IF;
  IF NOT ((OLD.status='DRAFT' AND NEW.status='PENDING_APPROVAL') OR
      (OLD.status='PENDING_APPROVAL' AND NEW.status IN ('APPROVED','REJECTED'))) THEN
    RAISE EXCEPTION 'Invalid reference fixing transition';
  END IF;
  IF OLD.status='PENDING_APPROVAL' AND (NEW.submitter_id,NEW.submitted_at) IS DISTINCT FROM (OLD.submitter_id,OLD.submitted_at) THEN
    RAISE EXCEPTION 'Reference contributor history is immutable';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER tr_srf_immutable BEFORE UPDATE OR DELETE ON m_savings_reference_fixing FOR EACH ROW EXECUTE FUNCTION savings_reference_fixing_immutable();
CREATE FUNCTION savings_reference_audit_immutable() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION 'Reference audit is append-only';
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER tr_sra_immutable BEFORE UPDATE OR DELETE ON m_savings_reference_audit FOR EACH ROW EXECUTE FUNCTION savings_reference_audit_immutable();
CREATE FUNCTION savings_reference_definition_immutable() RETURNS trigger AS $$
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Reference definitions are immutable'; END IF;
  IF (NEW.reference_id,NEW.reference_type,NEW.tenor,NEW.source_description,NEW.maker_id,NEW.created_at)
    IS DISTINCT FROM (OLD.reference_id,OLD.reference_type,OLD.tenor,OLD.source_description,OLD.maker_id,OLD.created_at) THEN
    RAISE EXCEPTION 'Reference identity is immutable';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER tr_srr_immutable BEFORE UPDATE OR DELETE ON m_savings_reference_rate FOR EACH ROW EXECUTE FUNCTION savings_reference_definition_immutable();
